import heapq

def shortest_path(edges, start, end):
    """
    最短距離と経路を返す関数（Dijkstra アルゴリズム）

    Args:
        edges: [(from_node, to_node, weight), ...] のリスト
        start: 開始ノード
        end: 終点ノード

    Returns:
        (distance, path) - 最短距離と経路のリスト（None あり）

    Raises:
        ValueError: 負の重みのエッジが含まれる場合
    """

    # 同じノードの場合は即座に処理
    if start == end:
        return (0, [start])

    # エッジを辞書形式に変換：{to_node: [(from_node, weight), ...]}
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        if to_node not in graph:
            # 逆方向のエッジがない場合のみ（有向グラフ）
            pass

        # 重みの負チェック
        if weight < 0:
            raise ValueError("エッジの重みが負です")

        graph[to_node].append((from_node, weight))

    # start が graph に存在しないなら、経路なし（ただしグラフ作成時の問題あり）
    if start not in graph and graph:
        return (None, None)

    # 最短距離の辞書（node -> min_dist）
    distances = {start: 0}
    # parent の辞書（再構築のため：to_node -> from_node）
    parents = {}

    # 優先度キュー（(distance, node)）
    queue = [(0, start)]

    # visited を管理
    visited = set()

    while queue:
        dist, node = heapq.heappop(queue)

        if node in visited:
            continue
        visited.add(node)

        # 終点に到達した場合は終了（ただしすべてのノードを処理する必要があるため注意）
        # ここは Dijkstra の通常の停止条件を使わない

        # 次へ移動可能なノードがあるか確認（存在しない場合も考慮）
        if node not in graph:
            continue

        for prev_node, weight in graph[node]:
            new_dist = dist + weight

            if prev_node not in distances or new_dist < distances[prev_node]:
                # 更新可能
                distances[prev_node] = new_dist
                parents[prev_node] = node
                heapq.heappush(queue, (new_dist, prev_node))

    # end が到達可能か確認
    if end not in distances:
        return (None, None)

    # 経路の再構築（end から start まで）
    path = []
    current = end
    while current != start:
        path.append(current)
        current = parents[current]
    path.append(start)
    path.reverse()

    return (distances[end], path)


# 簡易テスト例
if __name__ == "__main__":
    edges = [("A","B",1), ("B","C",2), ("A","C",5)]
    print(shortest_path(edges, "A", "C"))  # (3, ['A', 'B', 'C'])

    edges = [("X","Y",3)]
    print(shortest_path(edges, "Y", "X"))  # (None, None)

    edges = [("A","B",-1)]  # 負の重み
    try:
        shortest_path(edges, "A", "B")
    except ValueError as e:
        print(e)
